import type {
  SearchProps,
  SearchInputProps,
  SearchContentProps,
  SearchItemProps,
  SearchGroupProps,
  SearchLabelProps,
  SearchDividerProps,
  SearchClearIconButtonProps,
  SearchInputPrefixProps,
  SearchInputSuffixProps,
} from "./search.types";

import React, { forwardRef, useState, createContext, useContext } from "react";
import { clsx } from "clsx";
import { useTheme } from "@theme";
import { Combobox } from "@components/combobox";
import { IconButton } from "@components/icon-button";
import { Clear } from "@exp-textura/icons";

import { SearchClasses, StyledSearch } from "./search.styles";

const SearchRoot = forwardRef(
  (
    {
      className,
      variant = "default",
      styleSlots,
      children,
      showSelectedIndicator = false,
      openOnClick = false,
      ...props
    }: SearchProps,
    ref: React.ForwardedRef<HTMLDivElement>,
  ) => {
    const theme = useTheme();
    const rootClasses = clsx(SearchClasses.root, className);

    return (
      <StyledSearch
        ref={ref}
        as={StyledSearch}
        className={rootClasses}
        currentTheme={theme}
        openOnClick={openOnClick}
        showSelectedIndicator={showSelectedIndicator}
        styleSlots={styleSlots}
        variant={variant}
        {...props}
      >
        {children}
      </StyledSearch>
    );
  },
);
SearchRoot.displayName = "Search";

const SearchInput = forwardRef(
  (props: SearchInputProps, ref: React.ForwardedRef<HTMLInputElement>) => {
    const { className, ...rest } = props;
    const inputClasses = clsx(SearchClasses.input, className);

    return <Combobox.Input ref={ref} className={inputClasses} {...rest} />;
  },
);
SearchInput.displayName = "Search.Input";

const SearchInputPrefix = forwardRef(
  (props: SearchInputPrefixProps, ref: React.ForwardedRef<HTMLDivElement>) => {
    const { className, ...rest } = props;
    const prefixClasses = clsx(SearchClasses.prefix, className);

    return <Combobox.InputPrefix ref={ref} className={prefixClasses} {...rest} />;
  },
);
SearchInputPrefix.displayName = "Search.InputPrefix";

const SearchInputSuffix = forwardRef(
  (props: SearchInputSuffixProps, ref: React.ForwardedRef<HTMLDivElement>) => {
    const { className, ...rest } = props;
    const suffixClasses = clsx(SearchClasses.suffix, className);

    return <Combobox.InputSuffix ref={ref} className={suffixClasses} {...rest} />;
  },
);
SearchInputSuffix.displayName = "Search.InputSuffix";

const SearchContent = forwardRef(
  (props: SearchContentProps, ref: React.ForwardedRef<HTMLDivElement>) => {
    const { className, children, ...rest } = props;
    const contentClasses = clsx(SearchClasses.content, className);
    return (
      <Combobox.Content ref={ref} className={contentClasses} {...rest}>
        {children}
      </Combobox.Content>
    );
  },
);
SearchContent.displayName = "Search.Content";

const SearchItemContext = createContext({ isHovered: false });

const SearchItem = forwardRef<HTMLLIElement, SearchItemProps>((props, ref) => {
  const { className, children, ...rest } = props;
  const [isHovered, setIsHovered] = useState(false);
  const itemClasses = clsx(SearchClasses.item, className);

  return (
    <SearchItemContext.Provider value={{ isHovered }}>
      <Combobox.Item
        ref={ref}
        className={itemClasses}
        onMouseEnter={() => setIsHovered(true)}
        onMouseLeave={() => setIsHovered(false)}
        {...rest}
      >
        {children}
      </Combobox.Item>
    </SearchItemContext.Provider>
  );
});
SearchItem.displayName = "Search.Item";

const SearchItemRemoveIconButton = forwardRef(
  (props: React.ComponentProps<typeof IconButton>, ref: React.ForwardedRef<HTMLButtonElement>) => {
    const { children, style, className, variant, onClick, ...rest } = props;
    const { isHovered } = useContext(SearchItemContext);
    return (
      <IconButton
        ref={ref}
        buttonType="secondary"
        className={clsx(SearchClasses.removeItemButton, className)}
        size="sm"
        style={{ marginInlineStart: "auto", ...style }}
        variant={isHovered ? "inverse" : variant}
        onClick={(e) => {
          e.preventDefault();
          e.stopPropagation();
          onClick?.(e);
        }}
        onPointerDown={(e) => e.preventDefault()}
        {...rest}
      >
        {children || <Clear />}
      </IconButton>
    );
  },
);
SearchItemRemoveIconButton.displayName = "Search.ItemRemoveIconButton";

const SearchGroup = forwardRef(
  (props: SearchGroupProps, ref: React.ForwardedRef<HTMLDivElement>) => {
    const { className, ...rest } = props;
    return <Combobox.Group ref={ref} className={clsx(SearchClasses.group, className)} {...rest} />;
  },
);
SearchGroup.displayName = "Search.Group";

const SearchLabel = forwardRef(
  (props: SearchLabelProps, ref: React.ForwardedRef<HTMLDivElement>) => {
    const { className, ...rest } = props;
    return (
      <Combobox.Label ref={ref} className={clsx(SearchClasses.groupLabel, className)} {...rest} />
    );
  },
);

SearchLabel.displayName = "Search.Label";

const SearchDivider = forwardRef(
  (props: SearchDividerProps, ref: React.ForwardedRef<HTMLDivElement>) => {
    const { className, ...rest } = props;
    return (
      <Combobox.Divider ref={ref} className={clsx(SearchClasses.divider, className)} {...rest} />
    );
  },
);
SearchDivider.displayName = "Search.Divider";

const SearchClearIconButton: React.FC<SearchClearIconButtonProps> = ({ className, ...props }) => {
  return (
    <Combobox.ClearIconButton
      className={clsx(SearchClasses.clearIconButton, className)}
      {...props}
    />
  );
};
SearchClearIconButton.displayName = "Search.ClearIconButton";

const Search = Object.assign(SearchRoot, {
  Input: SearchInput,
  InputPrefix: SearchInputPrefix,
  InputSuffix: SearchInputSuffix,
  Content: SearchContent,
  Item: SearchItem,
  ItemRemoveIconButton: SearchItemRemoveIconButton,
  Group: SearchGroup,
  Label: SearchLabel,
  Divider: SearchDivider,
  ClearIconButton: SearchClearIconButton,
});

export default Search;
